/**
 * Subscribes a handler to an event and returns an unsubscribe function.
 */
export function subscribe(
  emitter: EventEmitter,
  event: string,
  handler: Listener
): () => void {
  const wrappedHandler = (...args: unknown[]) => handler(...args);
  emitter.on(event, wrappedHandler);

  return () => {
    emitter.off(event, wrappedHandler);
  };
}

