/**
 * Deep clones a value, handling nested objects, arrays, Dates,
 * and circular references.
 */
export function deepClone<T>(value: T, seen = new Map<object, object>()): T {
  if (value === null || typeof value !== 'object') {
    return value;
  }

  if (seen.has(value as object)) {
    return seen.get(value as object) as T;
  }

  if (value instanceof Date) {
    return new Date(value.getTime()) as unknown as T;
  }

  if (Array.isArray(value)) {
    const arrResult: unknown[] = [];
    seen.set(value as object, arrResult);
    for (const item of value) {
      arrResult.push(deepClone(item, seen));
    }
    return arrResult as unknown as T;
  }

  const result: Record<string, unknown> = {};
  seen.set(value as object, result);
  for (const key of Object.keys(value as Record<string, unknown>)) {
    result[key] = deepClone((value as Record<string, unknown>)[key], seen);
  }

  return result as T;
}

/**
 * Deep equality check for two values.
 */
export function deepEqual(a: unknown, b: unknown): boolean {
  if (a === b) return true;
  if (a === null || b === null) return false;
  if (typeof a !== typeof b) return false;

  if (a instanceof Date && b instanceof Date) {
    return a.getTime() === b.getTime();
