    this.cleanup(now);

    if (this.timestamps.length >= this.maxRequests) {
      return false;
    }

    this.timestamps.push(now);
    return true;
  }

  /**
   * Removes timestamps that are outside the current window.
   *
   * The window is inclusive: a request exactly `windowMs` milliseconds ago
